let section='all',jobQuery='',exploreQuery='',mini=null;
const clamp=(n,a=0,b=100)=>Math.max(a,Math.min(b,n));
function lifeInit(){if(!S.world){S.world={version:3,looks:68,fame:0,karma:65,stress:12,skills:Object.fromEntries(SKILLS.map(([k])=>[k,15])),family:[{id:'mother',name:'Ana',role:'Mãe',age:S.age+27,bond:82,alive:true},{id:'father',name:'Paulo',role:'Pai',age:S.age+30,bond:74,alive:true}],pets:[],married:false,degree:S.degree?'administration':null,course:null,club:null,company:null,followers:0,posts:0,trophies:0,works:[],special:null,experience:0,office:null,approval:40,prison:0,served:0,record:0,diseases:[],diet:'balanced',homes:[],holdings:{},prices:Object.fromEntries(STOCKS.map(s=>[s.id,s.price])),lastMarket:{},visited:[],achievements:[],generation:1,ancestors:[],will:'equal',collectibles:[],checkpoints:[],stamps:{},report:[],theme:'light',birthYear:2026-S.age};if(S.college){S.world.course={id:'administration',progress:S.college-1};S.college=0}for(let i=0;i<S.children;i++)S.world.family.push({id:'child-old-'+i,name:['Sofia','Miguel','Lara','Davi'][i%4],role:'Filho(a)',age:Math.max(0,S.age-22-i*2),bond:80,alive:true});}const w=S.world;if(S.partner&&!w.family.some(n=>n.role==='Parceiro(a)'&&n.alive))w.family.push({id:'partner-'+Date.now(),name:S.partner,role:'Parceiro(a)',age:Math.max(18,S.age),bond:S.relation,alive:true});if(!S.partner){w.married=false;w.family=w.family.filter(n=>n.role!=='Parceiro(a)')}for(const [id,_,test]of ACHIEVEMENTS)if(!w.achievements.includes(id)&&test(S))w.achievements.push(id)}
function tell(t,f){if(f)effects(f);log(t);render();toast(t)}
function spend(n){if(n<0||!Number.isFinite(n)||S.money<n){toast('Saldo insuficiente na carteira. Você pode resgatar dinheiro pelo celular.');return false}S.money=cents(S.money-n);return true}
function xp(skill,n=7){S.world.skills[skill]=clamp((S.world.skills[skill]||0)+n)}
function labelSkill(k){return SKILLS.find(x=>x[0]===k)?.[1]||k}
function nextFamilyId(){return 'f-'+Date.now()+'-'+Math.floor(Math.random()*1e6)}
function openResult(title,text){modal(`<span class="quiz-count">SUA HISTÓRIA</span><h2>${esc(title)}</h2><p>${esc(text)}</p><button class="btn primary" data-action="close">Continuar</button>`)}
function btn(label,action,disabled=false,klass='btn'){return `<button class="${klass}" data-action="x:${action}" ${disabled||!S.alive?'disabled':''}>${label}</button>`}
function tile(i,title,sub,action,tint='blue'){return `<button class="hub-tile tint-${tint}" data-action="x:${action}"><span class="hub-icon">${icon(i)}</span><span><strong>${title}</strong><small>${sub}</small></span><span class="chevron">›</span></button>`}
function heading(title,text=''){return `<div class="content-heading"><div><span class="eyebrow">SUA VIDA, SUAS ESCOLHAS</span><h2>${title}</h2>${text?`<p>${text}</p>`:''}</div>${btn('Voltar','section:all',false,'back-pill')}</div>`}
function summary(label,value,i='wallet'){return `<div class="mini-summary">${icon(i)}<span><small>${label}</small><strong>${value}</strong></span></div>`}
function pane(title,body,ic='star'){return `<article class="system-card"><div class="system-title"><span class="hub-icon">${icon(ic)}</span><h3>${title}</h3></div>${body}</article>`}
function field(id,label,value,type='number',extra=''){return `<label for="${id}">${label}</label><input id="${id}" type="${type}" value="${esc(value)}" ${extra}>`}
function resetSection(t){tab=t;section='all';render();window.scrollTo({top:0,behavior:'smooth'})}
const oldAct=act;
act=function(a){lifeInit();if(a.startsWith('x:'))return worldAction(a.slice(2));if(a==='new')return newLifeDialog();if(a==='start')return startNewLife();if(a==='college')return worldAction('section:education');if(a==='child')return worldAction('familyplan');if(a==='breakup'||a==='confirmBreak')return worldAction(a==='breakup'?'separate':'separateconfirm');if(S.world.prison>0&&!['advance','close','study','health','rest','family'].includes(a)&&!a.startsWith('p:')){toast('Você está cumprindo pena. As atividades da prisão estão em Explorar.');return}let oldJob=S.job,oldPartner=S.partner;oldAct(a);if(S.job!==oldJob){S.world.experience=0;S.world.special=null}if(S.partner!==oldPartner)lifeInit();save()};
const originalNetWorth=netWorth;
netWorth=function(){const base=originalNetWorth();if(!S.world)return base;return cents(base+S.world.homes.reduce((n,h)=>n+h.value-(h.debt||0),0)+STOCKS.reduce((n,s)=>n+(S.world.holdings[s.id]||0)*(S.world.prices[s.id]||s.price),0)+(S.world.company?Math.max(0,S.world.company.capital):0)+S.world.collectibles.reduce((n,c)=>n+c.value,0))};
const originalMonthly=monthlyCosts;
monthlyCosts=function(){let costs=originalMonthly();if(!S.world)return costs;if(S.world.homes.some(h=>h.residence))costs=costs.filter(c=>!['Aluguel','Manutenção do imóvel'].includes(c.label));if(S.world.prison>0)costs=costs.filter(c=>!['Alimentação','Internet e telefone'].includes(c.label));return [...costs,...S.world.pets.filter(p=>p.alive).map(p=>({label:'Cuidados · '+p.name,amount:p.cost})),...S.world.homes.map(h=>({label:'Condomínio · '+h.name,amount:h.cost})),...(S.world.diet==='premium'?[{label:'Alimentação especial',amount:180}]:[])]};
const originalNewYear=phoneNewYear;
phoneNewYear=function(){originalNewYear();if(!S.world||!S.phone)return;for(const h of S.world.homes)if(h.debt>0)billAdd('Financiamento · '+h.name,Math.min(h.debt,h.installment),'mortgage-'+S.age+'-'+h.id,'Parcela anual do financiamento · sem juros adicionais no jogo')};
const oldPayBill=payBill;
payBill=function(id,source,quiet=false){let b=S.phone.bills.find(b=>b.id===id);const ok=oldPayBill(id,source,quiet);if(ok&&b.key.startsWith('mortgage-')){let h=S.world.homes.find(h=>b.key.endsWith('-'+h.id));if(h)h.debt=Math.max(0,cents(h.debt-b.base))}return ok};
const extendedNetWorth=netWorth;netWorth=function(){return cents(extendedNetWorth()+(S.phone?.bills||[]).filter(b=>!b.paid&&b.key.startsWith('mortgage-')).reduce((n,b)=>n+b.base,0))};
JOBS.push(...[{name:'Auxiliar de cozinha',salary:1700,smart:20},{name:'Barista',salary:2100,smart:25},{name:'Recepcionista',salary:2200,smart:35},{name:'Vendedor',salary:2500,smart:30},{name:'Técnico de informática',salary:3500,smart:55},{name:'Designer',salary:4300,smart:60},{name:'Analista de marketing',salary:4900,smart:60},{name:'Jornalista',salary:5100,smart:65,degree:true},{name:'Contador',salary:5800,smart:65,degree:true},{name:'Enfermeiro',salary:6200,smart:70,degree:true},{name:'Advogado',salary:8500,smart:75,degree:true,field:'law'},{name:'Médico',salary:14000,smart:85,degree:true,field:'medicine'},{name:'Juiz',salary:28000,smart:90,degree:true,field:'law',rep:85},{name:'Pesquisador',salary:9200,smart:85,degree:true},{name:'Professor universitário',salary:11500,smart:85,degree:true,rep:65},{name:'Executivo financeiro',salary:21000,smart:85,degree:true,rep:80}].map(j=>({age:18,rep:20,...j})));
function newLifeDialog(){modal(`<span class="quiz-count">UMA VIDA INTEIRA PELA FRENTE</span><h2>Quem você quer ser?</h2><p>A vida atual será substituída. Suas escolhas começam aqui.</p>${field('name','Nome','Henri Silva','text','maxlength="36"')}<label for="city">Cidade</label><select id="city">${DESTINATIONS.filter(d=>d[1]==='Brasil').map(d=>`<option>${d[0]}</option>`).join('')}<option selected>São Paulo, SP</option><option>Recife, PE</option><option>Brasília, DF</option></select><label for="age">Começar em</label><select id="age"><option value="0">Nascimento</option><option value="6">6 anos · infância</option><option value="14" selected>14 anos · adolescência</option><option value="18">18 anos · vida adulta</option></select><label for="talent">Afinidade inicial</label><select id="talent"><option value="none">Descobrir pelo caminho</option>${SKILLS.map(([id,n])=>`<option value="${id}">${n}</option>`).join('')}</select><label for="background">Origem familiar</label><select id="background"><option value="simple">Família simples</option><option value="middle" selected>Classe média</option><option value="rich">Família rica</option></select><button class="btn primary" data-action="start">Começar minha história</button><button class="btn" data-action="close">Voltar</button>`)}
function startNewLife(){const talent=$('#talent')?.value||'none',bg=$('#background')?.value||'middle';S=fresh($('#name').value.trim()||'Alex Silva',$('#city').value,Number($('#age').value));lifeInit();if(talent!=='none')S.world.skills[talent]=45;S.money=bg==='rich'?(S.age>=18?150000:12000):bg==='simple'?(S.age>=18?1200:100):S.money;phoneInit();eventPick();$('#modal').close();phoneOpen=false;tab='life';section='all';render()}
function checkpoint(){const copy=JSON.parse(JSON.stringify(S));copy.world.checkpoints=[];S.world.checkpoints.unshift({age:S.age,snapshot:copy});S.world.checkpoints=S.world.checkpoints.slice(0,8)}
function yearlyBusiness(){const c=S.world.company;if(!c)return;const type=BUSINESSES.find(t=>t.id===c.type);let market=.65+Math.random()*.75;let priceFactor=clamp(type.price/c.price,.35,1.5),skill=.7+S.world.skills.business/160,capacity=2000+c.staff*1800+c.level*2000;let demand=Math.round(type.demand*market*priceFactor*skill*(1+c.marketing/20000));let maxAffordable=Math.max(0,Math.floor((c.capital-c.marketing)/type.unit));let sold=Math.max(0,Math.min(demand,capacity,maxAffordable));let revenue=sold*c.price,expense=sold*type.unit+type.fixed*c.level+c.staff*18000+c.marketing,profit=cents(revenue-expense);c.capital=cents(c.capital+profit);c.last={sold,revenue,expense,profit,market};c.marketing=0;c.years++;S.world.report.push({title:c.name,detail:`${sold} vendas · receita ${money(revenue)} · custos ${money(expense)}`,amount:profit});log(`${c.name}: ${sold} vendas, resultado de ${money(profit)} no ano.`);if(c.capital<0)log('Minha empresa ficou sem capital. Preciso investir ou encerrar as operações.')}
function yearlyWorld(){let w=S.world;w.report=[];w.experience+=S.job?1:0;for(const s of STOCKS){let before=w.prices[s.id],change=(Math.random()*2-1)*s.vol+.025;w.prices[s.id]=Math.max(1,cents(before*(1+change)));w.lastMarket[s.id]=Math.round(change*1000)/10}for(const h of w.homes){h.condition=clamp(h.condition-3-Math.random()*5);if(h.rented){let vacancy=Math.random()<(h.condition<50?.4:.15),annual=Math.round((vacancy?h.rent*8:h.rent*12)*Math.max(.5,h.condition/100));S.money=cents(S.money+annual);record('Aluguel recebido · '+h.name,annual);w.report.push({title:h.name,detail:vacancy?'4 meses sem inquilino':'12 meses de aluguel',amount:annual})}h.value=cents(h.value*(.97+Math.random()*.08))}yearlyBusiness();if(w.course){let course=DEGREES.find(d=>d.id===w.course.id);if(S.smarts>=course.min-10&&S.grade>=5){w.course.progress++;if(w.course.progress>=course.years){w.degree=course.id;S.degree=true;w.course=null;effects({smarts:7,reputation:10});log('Concluí minha graduação em '+course.name+'.')}}else log('Reprovei o ano da graduação. Preciso melhorar os estudos antes de avançar.')}if(w.special&&!['football','actor','music'].includes(w.special)&&w.prison===0){let career=CAREERS.find(c=>c.id===w.special);let performance=(w.skills[career.skill]+S.health)/2;w.fame=clamp(w.fame+(performance>65?5:-4));if(Math.random()<performance/160){w.trophies++;log('Meu trabalho como '+career.name.toLowerCase()+' recebeu reconhecimento.')}if(['football','fighter'].includes(w.special)&&S.age>=40){S.salary=Math.round(S.salary*.4);S.job='Treinador esportivo';w.special=null;log('Encerrei minha fase de competições e passei a treinar novos atletas.')}}if(w.followers>0){let annual=cents(w.followers*(.04+Math.random()*.1));S.money=cents(S.money+annual);record('Receita anual de conteúdo',annual);w.report.push({title:'Criação de conteúdo',detail:'Receita da comunidade',amount:annual});w.followers=Math.max(0,Math.round(w.followers*(w.stamps.post===S.age?1.05:.9)));}if(w.office){w.office.years--;w.approval=clamp(w.approval-8);if(w.office.years<=0){log('Meu mandato de '+w.office.name+' terminou. Posso disputar uma nova eleição.');w.office=null;S.job=null;S.salary=0}}if(w.prison>0){w.prison--;w.served++;if(!w.prison)log('Cumpri minha pena. Estou livre para reconstruir minha vida.')}for(const n of w.family.filter(n=>n.alive)){n.age++;n.bond=clamp(n.bond-2);if(n.age>=100||(n.age>75&&Math.random()<(n.age-75)/220)){n.alive=false;log(n.name+' faleceu aos '+n.age+' anos. Vou guardar nossas memórias.');effects({happy:-12});if(n.role==='Parceiro(a)'){S.partner=null;w.married=false}if(['Mãe','Pai'].includes(n.role)){let inheritance=Math.round(2000+Math.random()*18000);S.money+=inheritance;record('Herança de '+n.name,inheritance)}}}for(const p of w.pets.filter(p=>p.alive)){p.age++;p.health=clamp(p.health-5);if(p.age>p.years||p.health===0){p.alive=false;log('Me despedi de '+p.name+'. Foram anos de companhia.');effects({happy:-8})}else effects({happy:2})}if(Math.random()<(S.age>60?.22:.09)&&w.diseases.length<2){let illness=pick([{name:'Gripe',damage:5,cost:150},{name:'Dor crônica',damage:7,cost:450},{name:'Insônia',damage:4,cost:250}]);if(!w.diseases.some(d=>d.name===illness.name)){w.diseases.push(illness);log('Comecei a sentir sintomas de '+illness.name.toLowerCase()+'. Posso procurar atendimento em Saúde.')}}for(const d of w.diseases)effects({health:-d.damage});if(w.diet==='premium')effects({health:3});w.stress=clamp(w.stress+(S.job?4:-3));if(w.stress>75)effects({happy:-5,health:-3});if(w.club)xp(w.club,4);if(w.married){let partner=w.family.find(n=>n.role==='Parceiro(a)'&&n.alive);if(partner&&partner.bond<20&&Math.random()<.3){log('Meu casamento terminou após um longo afastamento.');S.partner=null;w.married=false;effects({happy:-10})}}}
advance=function(){if(!S.result||!S.alive)return;if(S.queue===0){S.queue=1;eventPick();render();return}checkpoint();S.queue=0;yearlyWorld();phoneYear();S.world.report.push({title:'Renda do trabalho',detail:'12 meses · '+(S.job||'Sem emprego'),amount:S.salary*12});S.age++;phoneNewYear();S.actions={};effects({health:S.age>65?-2:S.age>40?-1:0,happy:-2,relation:-2});if(S.age===18)log('Completei 18 anos. Carreiras, relacionamentos e responsabilidades ganharam uma nova dimensão.');if(S.health<=0||S.age>=105||(S.age>85&&Math.random()<(S.age-85)/220)){S.alive=false;log('Minha história chegou ao fim. Meu legado continua nas pessoas que fizeram parte dela.')}eventPick();lifeInit();render()};
const oldEventPick=eventPick;eventPick=function(){if(!S.world){oldEventPick();return}let pool=EVENTS.filter(e=>S.age>=e.min&&S.age<=e.max&&(!e.requires||e.requires(S))&&!S.seen.includes(e.id));if(!pool.length)pool=EVENTS.filter(e=>S.age>=e.min&&S.age<=e.max&&(!e.requires||e.requires(S)));S.event=pick(pool)?.id??0;S.result=null};
function peoplePage(){const w=S.world;return heading('As pessoas da sua vida','Relações têm história, idade e afeto próprios.')+`<div class="overview-strip">${summary('Seu momento',w.married?'Casado(a)':S.partner?'Namorando':'Solteiro(a)','heart')}${summary('Família',S.children+' filho(s)','people')}${summary('Geração',String(w.generation),'medal')}</div><div class="action-ribbon">${btn(S.partner?'Cuidar da relação':'Conhecer alguém','date')}${btn('Construir família','familyplan',S.age<18)}${btn('Fazer amizade','friend',S.age<6)}${btn('Animais de estimação','section:pets')}</div><div class="person-grid">${w.family.map(n=>`<article class="person-card ${n.alive?'':'memorial'}"><span class="person-avatar">${esc(n.name[0])}</span><div><span class="eyebrow">${n.role}</span><h3>${esc(n.name)}</h3><p>${n.age} anos · ${n.alive?'Na sua vida':'Em memória'}</p></div><div class="affection"><span>Afinidade <b>${n.bond}%</b></span><div class="bar"><i style="width:${n.bond}%"></i></div></div>${n.alive?btn('Conversar e interagir','person:'+n.id):'<span class="quiet">Uma história que fica.</span>'}</article>`).join('')}</div>`}
function peopleDetail(id){let n=S.world.family.find(n=>n.id===id);if(!n||!n.alive)return;modal(`<span class="quiz-count">${n.role.toUpperCase()} · ${n.age} ANOS</span><h2>${esc(n.name)}</h2><p>Afinidade: ${n.bond}%. Escolha como quer passar esse momento.</p>${btn('Conversar','bond:'+id+':talk')}${btn('Passear juntos · R$ 100','bond:'+id+':out',!canSpend(100))}${btn('Dar um presente · R$ 250','bond:'+id+':gift',!canSpend(250))}${btn('Resolver um conflito','bond:'+id+':resolve')}${n.role==='Parceiro(a)'?btn(S.world.married?'Conversar sobre separação':'Pedir em casamento',S.world.married?'separate':'marry'):''}${n.role==='Filho(a)'?btn('Financiar estudos · R$ 1.000','bond:'+id+':school',!canSpend(1000)):''}<button class="btn" data-action="close">Voltar</button>`)}
function educationPage(){let w=S.world;return heading('Educação & talentos','Aprenda, escolha sua formação e prepare seu futuro.')+`<div class="overview-strip">${summary('Média escolar',S.grade.toFixed(1),'school')}${summary('Formação',w.degree?DEGREES.find(d=>d.id===w.degree)?.name:'Em construção','book')}${summary('Intelecto',S.smarts+'%','brain')}</div><div class="system-grid">${pane('Escola',`<p>${S.age<6?'A escola começa aos 6 anos.':S.age<18?'Estude, participe de clubes e faça provas com nota.':'Sua etapa escolar foi concluída.'}</p><div class="action-ribbon"><button class="btn" data-action="study" ${S.age<6?'disabled':''}>Estudar</button><button class="btn" data-action="schoolQuiz" ${S.age<6||S.age>17?'disabled':''}>Fazer prova</button></div><label for="club">Atividade extracurricular</label><select id="club" data-world-change="club"><option value="">Sem clube</option>${SKILLS.map(([id,n])=>`<option value="${id}" ${w.club===id?'selected':''}>${n}</option>`).join('')}</select><p>O clube aumenta a habilidade escolhida a cada ano.</p>`,'school')}${pane('Autoescola',`<p>${S.cnh?'Você conquistou sua CNH. Explore sua garagem no celular.':'Passe pela prova teórica e pelas situações práticas de direção.'}</p><div class="action-ribbon"><button class="btn" data-action="cnhQuiz" ${S.age<18||S.theory||!canSpend(200)?'disabled':''}>Teoria · R$ 200</button><button class="btn" data-action="road" ${!S.theory||S.cnh||!canSpend(150)?'disabled':''}>Prática · R$ 150</button></div>`,'car')}</div><div class="content-heading"><h2>Universidade</h2>${w.course?`<span class="pill">${DEGREES.find(d=>d.id===w.course.id).name} · ${w.course.progress} anos concluídos</span>`:''}</div><div class="system-grid">${DEGREES.map(d=>pane(d.name,`<span class="badge">${d.years} ANOS · BOLSA INTEGRAL</span><p>Intelecto ${d.min}+ e média escolar 6+. A formação avança no aniversário com desempenho suficiente.</p>${btn(w.degree===d.id?'Formação concluída':w.course?.id===d.id?'Cursando':'Ingressar','enroll:'+d.id,S.age<18||w.course!==null||w.degree===d.id||S.smarts<d.min||S.grade<6)}`,'book')).join('')}</div>`}
function skillsPage(){return heading('Tudo o que você pode aprender','Pratique quantas vezes quiser. Habilidades abrem caminhos profissionais.')+`<div class="system-grid">${SKILLS.map(([id,n,i])=>pane(n,`<div class="skill-meter"><strong>${S.world.skills[id]}</strong><span>/100</span></div><div class="bar"><i style="width:${S.world.skills[id]}%"></i></div><p>${id==='sport'?'Treino, constância e novas competições.':id==='acting'?'Expressão, presença e interpretação.':id==='music'?'Técnica, ritmo e criatividade.':'Aprendizado para transformar suas oportunidades.'}</p>${btn('Praticar','train:'+id,S.age<6)}`,i)).join('')}</div>`}
function careersPage(){let w=S.world;return heading('Seu próximo capítulo profissional','Formação, reputação, habilidades e experiência contam.')+`<div class="overview-strip">${summary('Ocupação',S.job||'Sem emprego','work')}${summary('Renda mensal',money(S.salary),'wallet')}${summary('Experiência',w.experience+' anos','medal')}</div><div class="action-ribbon">${btn('Educação','section:education')}${btn('Treinar habilidades','section:skills')}${btn('Abrir empresa','section:business')}${btn('Política','section:politics')}</div>${S.job?pane('Seu trabalho',`<p>Reputação ${S.reputation}% · Estresse ${w.stress}%</p><div class="action-ribbon">${btn('Melhorar desempenho','perform')}${btn('Pedir aumento','raise',S.actions.raise)}${btn('Conversar com a chefia','boss')}${btn('Pedir demissão','quit')}${S.age>=65?'<button class="btn" data-action="retire">Aposentar-se</button>':''}</div>`,'work'):''}<div class="content-heading"><h2>Carreiras especiais</h2><span class="pill">10 caminhos</span></div><div class="system-grid">${CAREERS.map(c=>pane(c.name,`<span class="badge">A PARTIR DE ${money(c.pay)}/MÊS</span><p>${labelSkill(c.skill)} ${c.need}+${c.looks?' · Aparência '+c.looks+'+':''}${c.degree?' · Graduação'+(c.degree!=='any'?' em '+DEGREES.find(d=>d.id===c.degree).name:''):''} · ${c.age}+ anos.</p>${btn(w.special===c.id?'Carreira atual':'Fazer seleção','special:'+c.id,S.age<c.age||w.skills[c.skill]<c.need||(c.looks&&w.looks<c.looks)||(c.degree&&(c.degree==='any'?!S.degree:w.degree!==c.degree))||w.special===c.id)}${w.special===c.id?btn('Desafio da carreira','specialevent:'+c.id):''}`,c.icon)).join('')}</div><div class="content-heading"><h2>Mercado de trabalho</h2><span class="pill">${JOBS.length} profissões</span></div><div class="system-grid">${JOBS.map((j,i)=>pane(j.name,`<span class="badge">${money(j.salary)}/MÊS</span><p>Intelecto ${j.smart}+ · Reputação ${j.rep}+${j.field?' · '+DEGREES.find(d=>d.id===j.field).name:j.degree?' · Ensino superior':''}${j.cnh?' · CNH':''}</p>${btn(S.job===j.name?'Emprego atual':'Candidatar-se','job:'+i,S.age<j.age||S.smarts<j.smart||S.reputation<j.rep||(j.degree&&!S.degree)||(j.field&&w.degree!==j.field)||(j.cnh&&!S.cnh)||S.job===j.name)}`,'work')).join('')}</div>`}
function businessPage(){let c=S.world.company;return heading('Construa algo seu','Preço, equipe, capital e demanda determinam o resultado anual.')+(c?`<div class="overview-strip">${summary('Empresa',esc(c.name),'work')}${summary('Capital',money(c.capital),'wallet')}${summary('Último resultado',money(c.last?.profit||0),'chart')}</div><div class="system-grid">${pane('Operação',`<p>${BUSINESSES.find(t=>t.id===c.type).name} · nível ${c.level} · ${c.staff} funcionários</p>${field('product-price','Preço do produto / serviço',c.price,'number','min="1" step="1"')}${field('staff-count','Número de funcionários',c.staff,'number','min="0" max="100"')}${btn('Salvar operação','businesssave')}<p>Salário por funcionário: R$ 18.000/ano. O relatório inclui insumos, custo fixo e marketing.</p>`,'work')}${pane('Crescimento',`<p>Marketing aumenta a demanda; expansão aumenta capacidade e custos. O capital da empresa é separado da carteira.</p><div class="action-ribbon">${btn('Aportar R$ 10.000','businessfund',!canSpend(10000))}${btn('Retirar R$ 5.000','businesswithdraw',c.capital<5000)}${btn('Marketing · R$ 3.000','businessmarket',c.capital-c.marketing<3000)}${btn('Expandir · R$ 30.000','businessexpand',c.capital<30000)}${btn('Encerrar empresa','businessclose')}</div>`,'chart')}</div>${c.last?pane('Relatório do último ano',`<div class="detail-line"><span>Vendas</span><b>${c.last.sold}</b></div><div class="detail-line"><span>Receita</span><b>${money(c.last.revenue)}</b></div><div class="detail-line"><span>Custos totais</span><b>${money(c.last.expense)}</b></div><div class="detail-line"><span>Resultado</span><b>${money(c.last.profit)}</b></div>`,'bill'):''}`:`<div class="system-grid">${BUSINESSES.map(b=>pane(b.name,`<span class="badge">CAPITAL INICIAL ${money(b.capital)}</span><p>Custo por venda: ${money(b.unit)}. Preço sugerido: ${money(b.price)}. Custo fixo anual: ${money(b.fixed)}. Mercado com ${b.demand.toLocaleString('pt-BR')} vendas potenciais por ano.</p>${btn('Abrir empresa','businessnew:'+b.id,S.age<18||!canSpend(b.capital))}`,'work')).join('')}</div>`)}
function healthPage(){let w=S.world;return heading('Corpo & mente','Cuide da rotina e acompanhe como você se sente.')+`<div class="overview-strip">${summary('Saúde',S.health+'%','heart')}${summary('Estresse',w.stress+'%','brain')}${summary('Aparência',w.looks+'%','star')}</div><div class="system-grid">${pane('Atendimento médico',`<p>${w.diseases.length?w.diseases.map(d=>d.name).join(' · '):'Nenhum problema de saúde identificado.'}</p>${btn('Consulta na rede pública','doctor:public')}${btn('Consulta particular · R$ 450','doctor:private',!canSpend(450))}<p>Na simulação, cada consulta tem uma chance de recuperação. Sintomas não tratados podem reduzir sua saúde no aniversário.</p>`,'heart')}${pane('Bem-estar',`<div class="action-ribbon">${btn('Exercício físico','well:exercise')}${btn('Meditar','well:meditate')}${btn('Psicoterapia · R$ 180','well:therapy',!canSpend(180))}${btn('Salão · R$ 120','well:salon',!canSpend(120))}${btn('Spa · R$ 300','well:spa',!canSpend(300))}</div><label for="diet">Rotina alimentar</label><select id="diet" data-world-change="diet"><option value="balanced" ${w.diet==='balanced'?'selected':''}>Equilibrada · sem custo extra</option><option value="premium" ${w.diet==='premium'?'selected':''}>Acompanhada · +R$ 180/mês</option></select>`,'sun')}</div>`}
function petsPage(){return heading('Companheiros de vida','Adote, dê um nome e acompanhe seu animal por muitos anos.')+`<div class="person-grid">${S.world.pets.map(p=>`<article class="person-card"><span class="person-avatar">${icon('pet')}</span><div><span class="eyebrow">${PETS.find(t=>t.id===p.type)?.name}</span><h3>${esc(p.name)}</h3><p>${p.age} anos · ${p.alive?'Saúde '+p.health+'%':'Em memória'}</p></div>${p.alive?`<div class="action-ribbon">${btn('Brincar','petcare:'+p.id+':play')}${btn('Veterinário · R$ 180','petcare:'+p.id+':vet',!canSpend(180))}</div>`:''}</article>`).join('')}</div><div class="content-heading"><h2>Encontre seu companheiro</h2></div><div class="system-grid">${PETS.map(p=>pane(p.name,`<p>Adoção: ${money(p.price)}. Cuidados: ${money(p.cost)}/mês, incluídos nos boletos anuais.</p>${btn('Adotar','adoptpet:'+p.id,!canSpend(p.price))}`,'pet')).join('')}</div>`}
function propertiesPage(){return heading('Um lugar para chamar de seu','More, alugue, reforme ou venda. Os imóveis fazem parte do seu patrimônio.')+`<div class="overview-strip">${summary('Imóveis',S.world.homes.length,'home')}${summary('Renda potencial mensal',money(S.world.homes.filter(h=>h.rented).reduce((n,h)=>n+h.rent,0)),'wallet')}</div><div class="system-grid">${S.world.homes.map(h=>pane(h.name,`<span class="badge">${h.residence?'SUA RESIDÊNCIA':h.rented?'ALUGADO':'DESOCUPADO'} · CONSERVAÇÃO ${Math.round(h.condition)}%</span><p>Valor: ${money(h.value)}. Aluguel: ${money(h.rent)}/mês. ${h.debt?'Financiamento restante: '+money(h.debt):'Quitado.'}</p><div class="action-ribbon">${btn(h.residence?'Morar aqui':'Mudar para cá','homeuse:'+h.id,h.residence)}${btn(h.rented?'Encerrar aluguel':'Alugar','homerent:'+h.id,h.residence)}${btn('Reformar · R$ 5.000','homerepair:'+h.id,!canSpend(5000))}${btn('Vender','homesell:'+h.id)}</div>`,'home')).join('')}</div><div class="content-heading"><h2>Mercado imobiliário</h2></div><div class="system-grid">${PROPERTIES.map(p=>pane(p.name,`<div class="price-display">${money(p.price)}</div><p>Condomínio: ${money(p.cost)}/mês. Aluguel sugerido: ${money(p.rent)}/mês.</p>${btn('Ver opções de compra','homebuy:'+p.id,S.age<18)}`,'home')).join('')}</div>`}
function marketPage(){let w=S.world,total=STOCKS.reduce((n,s)=>n+(w.holdings[s.id]||0)*w.prices[s.id],0);return heading('Seus investimentos','Cotações fictícias mudam a cada ano. Ganhos e perdas afetam seu patrimônio.')+`<div class="overview-strip">${summary('Valor da carteira',money(total),'chart')}${summary('Disponível',money(S.money),'wallet')}</div><div class="system-grid">${STOCKS.map(s=>pane(s.name,`<span class="badge">${s.symbol} · ${s.desc}</span><div class="market-quote"><strong>${money(w.prices[s.id])}</strong><span class="${(w.lastMarket[s.id]||0)>=0?'positive':'negative'}">${(w.lastMarket[s.id]||0)>0?'+':''}${w.lastMarket[s.id]||0}% no ano</span></div><p>Você tem ${w.holdings[s.id]||0} cotas · ${money((w.holdings[s.id]||0)*w.prices[s.id])}</p><div class="action-ribbon">${btn('Comprar','stock:'+s.id+':buy',S.age<18)}${btn('Vender','stock:'+s.id+':sell',!(w.holdings[s.id]>0))}</div>`,'chart')).join('')}</div>`}
function famePage(){let w=S.world;return heading('Talento, palco & público','Crie, lance projetos e construa sua própria audiência.')+`<div class="overview-strip">${summary('Fama',w.fame+'%','star')}${summary('Seguidores',w.followers.toLocaleString('pt-BR'),'people')}${summary('Reconhecimentos',w.trophies,'medal')}</div><div class="system-grid">${pane('Sua comunidade',`<p>${w.posts} publicações. A resposta depende de habilidade, fama e sorte. Nem todo conteúdo cresce.</p><div class="action-ribbon">${btn('Criar uma publicação','post',S.age<13)}${btn('Transmitir ao vivo','live',S.age<13)}${btn('Campanha publicitária','ad',w.followers<10000)}${btn('Dar uma entrevista','interview',w.fame<20)}</div>`,'people')}${pane('Produza sua próxima obra',`<p>Lançamentos podem dar lucro ou prejuízo. Treine a habilidade relacionada para melhorar suas chances.</p><div class="action-ribbon">${btn('Lançar música · R$ 2.000','release:music',S.age<16||!canSpend(2000))}${btn('Publicar livro · R$ 1.500','release:book',S.age<16||!canSpend(1500))}${btn('Produzir filme · R$ 15.000','release:film',S.age<18||!canSpend(15000))}</div>`,'film')}</div><div class="content-heading"><h2>Seu catálogo</h2></div>${w.works.length?`<div class="system-grid">${w.works.slice(0,20).map(a=>pane(esc(a.title),`<span class="badge">${a.type} · NOTA ${a.rating}/10</span><p>Lançado aos ${a.age} anos. Receita: ${money(a.revenue)}. Custo: ${money(a.cost)}.</p>`,'star')).join('')}</div>`:'<div class="glass-empty">Sua primeira obra começa com uma ideia.</div>'}`}
function politicsPage(){let w=S.world;return heading('Vida pública','Reputação, oratória e aprovação influenciam as eleições.')+`<div class="overview-strip">${summary('Mandato',w.office?.name||'Sem cargo','people')}${summary('Aprovação',w.approval+'%','heart')}${summary('Oratória',w.skills.speech+'%','brain')}</div>${w.office?pane('Seu mandato',`<p>${w.office.years} anos restantes. Renda mensal: ${money(S.salary)}.</p><div class="action-ribbon">${btn('Priorizar educação','policy:education')}${btn('Priorizar saúde','policy:health')}${btn('Ouvir a população','policy:listen')}</div>`,'people'):''}<div class="system-grid">${[{id:'council',name:'Vereador(a)',age:18,cost:5000},{id:'mayor',name:'Prefeito(a)',age:21,cost:20000},{id:'governor',name:'Governador(a)',age:30,cost:100000},{id:'president',name:'Presidente',age:35,cost:500000}].map(p=>pane(p.name,`<p>Campanha: ${money(p.cost)}. Idade mínima no jogo: ${p.age} anos. Mandato de 4 anos.</p>${btn('Disputar eleição','election:'+p.id,S.age<p.age||!canSpend(p.cost)||!!w.office||w.record>0)}`,'crown')).join('')}</div>`}
function travelPage(){return heading('O mundo lá fora','Viaje, colecione experiências ou recomece em outra cidade.')+`<div class="overview-strip">${summary('Você está em',esc(S.city),'pin')}${summary('Destinos visitados',S.world.visited.length,'plane')}</div><div class="system-grid">${DESTINATIONS.map(([city,country,cost],i)=>pane(city,`<span class="badge">${country.toUpperCase()}</span><p>Viagem: ${money(cost)}. Mudança definitiva: ${money(cost*3)}. Empregos presenciais são encerrados ao mudar de cidade.</p><div class="action-ribbon">${btn('Viajar','trip:'+i,S.age<18||!canSpend(cost))}${btn('Mudar de cidade','move:'+i,S.age<18||!canSpend(cost*3))}</div>`,'plane')).join('')}</div>`}
function justicePage(){let w=S.world;return heading('Escolhas & consequências','Decisões arriscadas podem custar dinheiro, reputação e liberdade.')+`<div class="overview-strip">${summary('Situação',w.prison?w.prison+' anos de pena':'Em liberdade','shield')}${summary('Condenações',w.record,'bill')}${summary('Karma',w.karma+'%','sun')}</div>${w.prison?`<div class="system-grid">${pane('Durante a pena',`<p>O tempo da pena diminui a cada aniversário. Seu emprego foi encerrado.</p><div class="action-ribbon">${btn('Estudar na biblioteca','prisonstudy')}${btn('Trabalhar na prisão','prisonwork')}${btn('Pedir revisão · R$ 2.000','appeal',!canSpend(2000))}${btn('Desafio de fuga','escape')}</div>`,'lock')}</div>`:`<div class="system-grid">${[{id:'shop',name:'Pequeno furto',reward:400,risk:40,years:1},{id:'fraud',name:'Fraude financeira',reward:7000,risk:65,years:4},{id:'robbery',name:'Assalto',reward:18000,risk:80,years:7}].map(c=>pane(c.name,`<p>Risco de ser detido: ${c.risk}%. Resultado possível: até ${money(c.reward)}. Pena no jogo: ${c.years} anos.</p>${btn('Tomar essa decisão','crime:'+c.id,S.age<18)}`,'shield')).join('')}${pane('Resolver um conflito',`<p>Um acordo encerra um conflito pessoal sem recorrer a decisões arriscadas.</p>${btn('Buscar mediação · R$ 300','mediation',!canSpend(300))}`,'people')}</div>`}`}
function gamesPage(){return heading('Entre uma escolha e outra','Minijogos com consequências, aprendizado e recompensas dentro da vida.')+`<div class="system-grid">${pane('Memória',`<p>Memorize uma sequência e exercite o intelecto.</p><button class="btn" data-action="memory" ${S.age<6?'disabled':''}>Jogar</button>`,'brain')}${pane('Campeonato de pênaltis',`<p>Escolha o canto, vença o goleiro e dispute um troféu em cinco cobranças.</p>${btn('Entrar em campo','penalty',S.age<8)}`,'bolt')}${pane('Operação lógica',`<p>Encontre cinco células seguras em um campo com três minas. Uma prova de raciocínio para a carreira militar.</p>${btn('Começar desafio','mines',S.age<12)}`,'grid')}${pane('21 · Jogo de cartas',`<p>Tente chegar a 21 sem ultrapassar. Aposta fictícia de R$ 100, sem dinheiro real.</p>${btn('Jogar · R$ 100','blackjack',S.age<18||!canSpend(100))}`,'star')}${pane('Sorteio da cidade',`<p>Bilhete fictício: R$ 10. Chance de 1 em 10.000 de ganhar R$ 50.000. Sem dinheiro real.</p>${btn('Comprar bilhete','lottery',S.age<18||!canSpend(10))}`,'medal')}</div>`}
function legacyPage(){let w=S.world;return heading('O que fica de você','Conquistas, memórias e caminhos para a próxima geração.')+`<div class="overview-strip">${summary('Conquistas',w.achievements.length+'/'+ACHIEVEMENTS.length,'medal')}${summary('Geração',w.generation,'people')}${summary('Legado financeiro',money(netWorth()),'wallet')}</div><div class="system-grid">${pane('Seu testamento',`<p>Ao continuar com um herdeiro, o patrimônio é liquidado e as dívidas são descontadas. Os filhos vivos recebem a divisão definida.</p><label for="will">Distribuição da herança</label><select id="will" data-world-change="will"><option value="equal" ${w.will==='equal'?'selected':''}>Dividir entre todos os filhos</option><option value="first" ${w.will==='first'?'selected':''}>Deixar tudo para o primeiro filho vivo</option></select>${!S.alive?`<button class="btn primary" data-action="x:inherit">Continuar com um herdeiro</button>`:''}`,'book')}${pane('Revisitar uma decisão',`<p>Restaure um dos últimos oito anos. Saldo, família, eventos e aplicativos retornam juntos àquele momento.</p>${w.checkpoints.length?w.checkpoints.map((c,i)=>`<button class="btn" data-action="x:rewind:${i}">Voltar aos ${c.age} anos</button>`).join(''):'<p>Seu primeiro ponto será criado ao avançar um ano.</p>'}`,'refresh')}</div><div class="content-heading"><h2>Suas conquistas</h2></div><div class="achievement-grid">${ACHIEVEMENTS.map(([id,n,_,ic])=>`<div class="achievement ${w.achievements.includes(id)?'unlocked':''}">${icon(ic)}<strong>${n}</strong><small>${w.achievements.includes(id)?'Conquistado':'Ainda por viver'}</small></div>`).join('')}</div>${w.ancestors.length?`<div class="content-heading"><h2>Antes de você</h2></div>${w.ancestors.map(a=>pane(esc(a.name),`<p>${a.age} anos · ${esc(a.job||'Uma vida de possibilidades')} · Legado ${money(a.worth)}</p>`,'people')).join('')}`:''}`}
const HUBS=[['education','school','Educação','Escola, faculdade e CNH','blue'],['skills','brain','Habilidades','Oito formas de crescer','purple'],['health','heart','Saúde & beleza','Corpo, mente e bem-estar','pink'],['pets','pet','Animais','Companheiros para a vida','orange'],['business','work','Empresas','Construa o seu negócio','blue'],['properties','home','Imóveis','Comprar, morar e alugar','cyan'],['market','chart','Investimentos','Uma carteira de possibilidades','green'],['fame','star','Fama & entretenimento','Podcasts, TV e sua comunidade','purple'],['politics','people','Vida pública','Campanhas e mandatos','orange'],['travel','plane','Viagens & mudança','Seu lugar no mundo','cyan'],['justice','shield','Escolhas arriscadas','Liberdade e consequências','pink'],['games','grid','Minijogos','Memória, esporte e desafios','green'],['legacy','medal','Legado','Conquistas e gerações','orange'],['collection','book','Coleções','Tesouros e memórias','purple']];
function hubPage(){return heading('Existe uma vida inteira aqui','Escolha o que quer viver agora.')+`<div class="hub-grid">${HUBS.map(([id,i,n,d,c])=>tile(i,n,d,'section:'+id,c)).join('')}</div>`}
function collectionPage(){return heading('Histórias que cabem nas mãos','Objetos especiais para guardar, negociar e deixar como lembrança.')+pane('Sótão da família',`<p>Uma vez a cada ano da vida, procure um objeto esquecido. O valor e a raridade variam.</p>${btn('Explorar o sótão','heirloom',S.world.stamps.heirloom===S.age)}`,'book')+`<div class="system-grid">${S.world.collectibles.map((c,i)=>pane(c.name,`<span class="badge">${c.rarity}</span><div class="price-display">${money(c.value)}</div><p>Encontrado aos ${c.age} anos.</p>${btn('Vender','collectsell:'+i)}`,'star')).join('')}</div>`}
const SECTION_PAGES={education:educationPage,skills:skillsPage,health:healthPage,pets:petsPage,business:businessPage,properties:propertiesPage,market:marketPage,fame:famePage,politics:politicsPage,travel:travelPage,justice:justicePage,games:gamesPage,legacy:legacyPage,collection:collectionPage};
function worldAction(raw){lifeInit();phoneInit();const [a,id,arg]=raw.split(':'),w=S.world;if(a==='section'){section=id;render();window.scrollTo({top:0,behavior:'smooth'});return}if(a==='theme'){w.theme=w.theme==='light'?'dark':'light';render();return}if(a==='inherit')return inheritDialog();if(a==='inheritconfirm')return inheritLife(id);if(a==='rewind'){let point=w.checkpoints[+id];if(!point)return;modal(`<h2>Revisitar os ${point.age} anos?</h2><p>As escolhas posteriores serão substituídas pelo estado salvo daquele ano. Isso inclui todas as contas e compras.</p><button class="btn primary" data-action="x:rewindconfirm:${id}">Restaurar esse ano</button><button class="btn" data-action="close">Voltar</button>`);return}if(a==='rewindconfirm'){let point=w.checkpoints[+id];if(!point)return;let older=w.checkpoints.slice(+id+1);S=JSON.parse(JSON.stringify(point.snapshot));S.world.checkpoints=older;$('#modal').close();phoneOpen=false;tab='life';section='all';render();toast('Sua história voltou aos '+S.age+' anos.');return}if(!S.alive)return;if(w.prison>0&&!['prisonstudy','prisonwork','appeal','escape','escapeStep','mediation','theme'].includes(a)){toast('Você está cumprindo pena. Acesse as atividades da prisão.');return}
if(a==='train'){if(S.age<6||!SKILLS.some(s=>s[0]===id))return;xp(id);if(id==='sport')effects({health:2});if(id==='speech')effects({reputation:1});tell('Pratiquei '+labelSkill(id).toLowerCase()+'. Minha habilidade está em '+w.skills[id]+'%.');return}
if(a==='enroll'){let d=DEGREES.find(d=>d.id===id);if(!d||S.age<18||w.course||w.degree===id||S.smarts<d.min||S.grade<6)return;w.course={id,progress:0};S.college=0;tell('Entrei na graduação em '+d.name+'. Vou construir essa formação ao longo dos próximos '+d.years+' anos.');return}
if(a==='job'){let j=JOBS[+id];if(!j||(j.field&&w.degree!==j.field))return;act('job'+id);return}
if(a==='special'){let c=CAREERS.find(c=>c.id===id);if(!c||S.age<c.age||w.skills[c.skill]<c.need||(c.looks&&w.looks<c.looks)||(c.degree&&(c.degree==='any'?!S.degree:w.degree!==c.degree)))return;let chance=.45+w.skills[c.skill]/250;if(Math.random()<chance){S.job=c.name;S.salary=c.pay;w.special=id;w.experience=0;w.fame=clamp(w.fame+5);tell('Passei na seleção de '+c.name+'. Minha nova carreira começou.')}else tell('A seleção não deu certo desta vez. Posso treinar e tentar outra oportunidade.',{happy:-2});return}
if(a==='specialevent'){if(w.special!==id)return;if(['football','fighter'].includes(id))return startPenalty();if(['military','astronaut','agent'].includes(id))return startMines();if(id==='music')return releaseDialog('music');if(id==='writer')return releaseDialog('book');return releaseDialog('film')}
if(a==='perform'){if(!S.job)return;effects({reputation:5});w.stress=clamp(w.stress+2);tell('Me dediquei ao trabalho e melhorei minha reputação.');return}if(a==='boss'){if(!S.job)return;tell('Conversei com a chefia sobre meu desenvolvimento profissional.',{reputation:3});return}if(a==='raise'){if(!S.job||S.actions.raise)return;S.actions.raise=true;if(S.reputation>=60&&w.experience>=1){S.salary=Math.round(S.salary*1.08);tell('Recebi um aumento de 8%. Minha renda mensal é '+money(S.salary)+'.')}else tell('O aumento não foi aprovado. Preciso de reputação 60+ e pelo menos um ano nesse trabalho.');return}if(a==='quit'){if(!S.job)return;modal(`<h2>Encerrar seu trabalho?</h2><p>Você deixará de receber ${money(S.salary)} por mês e poderá buscar outro caminho.</p>${btn('Confirmar demissão','quitconfirm')}<button class="btn" data-action="close">Voltar</button>`);return}if(a==='quitconfirm'){S.job=null;S.salary=0;w.special=null;w.office=null;$('#modal').close();tell('Encerrei meu trabalho e comecei a buscar novos caminhos.');return}
if(a==='date'){act('date');return}if(a==='friend'){if(S.age<6)return;const name=pick(['Bruno','Luiza','Caio','Manuela','Ravi','Isabela','Theo','Helena']);w.family.push({id:nextFamilyId(),name,role:'Amigo(a)',age:Math.max(6,S.age+Math.floor(Math.random()*5)-2),bond:45+Math.floor(Math.random()*20),alive:true});tell('Fiz amizade com '+name+'.',{happy:4});return}if(a==='person')return peopleDetail(id);
if(a==='bond'){let n=w.family.find(n=>n.id===id&&n.alive);if(!n)return;const prices={talk:0,out:100,gift:250,resolve:0,school:1000};if(!(arg in prices)||!spend(prices[arg]))return;let gain=arg==='gift'?12:arg==='school'?15:arg==='resolve'?5:8;n.bond=clamp(n.bond+gain);if(n.role==='Parceiro(a)')S.relation=n.bond;$('#modal').close();tell('Passei um momento importante com '+n.name+'.',{happy:4,relation:2});return}
if(a==='marry'){if(S.age<18||!S.partner||w.married)return;modal(`<h2>Dar esse próximo passo?</h2><p>Organizar um casamento com ${esc(S.partner)} custa R$ 5.000 no jogo. Uma relação próxima aumenta a chance de um sim.</p>${btn('Fazer o pedido · R$ 5.000','marryconfirm',!canSpend(5000))}<button class="btn" data-action="close">Voltar</button>`);return}if(a==='marryconfirm'){if(!S.partner||w.married||S.age<18||!spend(5000))return;let n=w.family.find(n=>n.role==='Parceiro(a)'&&n.alive);$('#modal').close();if(n&&n.bond>=50){w.married=true;tell('Eu e '+S.partner+' nos casamos. Um novo capítulo da nossa família começou.',{happy:15})}else tell('O pedido não foi aceito. Precisamos cuidar melhor da relação.',{happy:-5});return}
if(a==='separate'){if(!S.partner)return;modal(`<h2>${w.married?'Encerrar o casamento':'Encerrar a relação'}?</h2><p>${w.married?'A separação transfere 25% do saldo positivo da carteira ao parceiro, conforme as regras do jogo.':'Vocês seguirão caminhos diferentes.'} Os filhos continuam na sua família.</p>${btn('Confirmar separação','separateconfirm')}<button class="btn" data-action="close">Voltar</button>`);return}if(a==='separateconfirm'){if(!S.partner)return;let ex=S.partner;if(w.married)S.money=cents(S.money-Math.max(0,S.money)*.25);let n=w.family.find(n=>n.role==='Parceiro(a)');if(n){n.role='Ex-parceiro(a)';n.bond=25}S.partner=null;w.married=false;$('#modal').close();tell('Eu e '+ex+' encerramos nossa relação.',{happy:-10});return}
if(a==='familyplan'){if(S.age<18)return;modal(`<h2>Uma família do seu jeito.</h2><p>Uma criança tem nome, idade e laços próprios. Custos de criação: R$ 650/mês por filho.</p>${field('child-name','Nome da criança',pick(['Sofia','Miguel','Clara','Davi','Helena','Gael']),'text','maxlength="30"')}${btn('Planejar bebê · R$ 3.000','childadd:baby',!S.partner||S.age>50||!canSpend(3000))}${btn('Iniciar adoção · R$ 2.000','childadd:adopt',S.age<21||!canSpend(2000))}<button class="btn" data-action="close">Voltar</button>`);return}if(a==='childadd'){if(S.age<18||(id==='baby'&&(!S.partner||S.age>50))||(id==='adopt'&&S.age<21)||!['baby','adopt'].includes(id))return;let name=$('#child-name').value.trim().slice(0,30)||'Alex';if(!spend(id==='baby'?3000:2000))return;S.children++;w.family.push({id:nextFamilyId(),name,role:'Filho(a)',age:id==='baby'?0:3,bond:90,alive:true});$('#modal').close();tell(name+' chegou à nossa família.',{happy:15});return}
if(a==='adoptpet'){let p=PETS.find(p=>p.id===id);if(!p)return;modal(`<h2>Adotar um ${p.name.toLowerCase()}</h2><p>Adoção: ${money(p.price)}. Cuidados mensais: ${money(p.cost)}.</p>${field('pet-name','Nome do animal',pick(['Bento','Mel','Nina','Pipoca','Chico']),'text','maxlength="25"')}${btn('Confirmar adoção','adoptpetconfirm:'+id,!canSpend(p.price))}<button class="btn" data-action="close">Voltar</button>`);return}if(a==='adoptpetconfirm'){let p=PETS.find(p=>p.id===id);if(!p||!spend(p.price))return;let name=$('#pet-name').value.trim().slice(0,25)||'Bento';w.pets.push({...p,id:nextFamilyId(),type:id,name,age:0,health:90,alive:true});$('#modal').close();tell('Adotei '+name+'. Ganhei uma nova companhia.',{happy:8});return}if(a==='petcare'){let p=w.pets.find(p=>p.id===id&&p.alive);if(!p)return;if(arg==='vet'&&!spend(180))return;p.health=clamp(p.health+(arg==='vet'?25:4));tell('Cuidei de '+p.name+'.',{happy:4});return}
if(a==='doctor'){if(id==='private'&&!spend(450))return;let chance=id==='private'?.9:.65;if(w.diseases.length&&Math.random()<chance){let illness=w.diseases.shift();tell('Após atendimento, me recuperei de '+illness.name.toLowerCase()+'.',{health:12})}else tell(w.diseases.length?'Passei por atendimento, mas a recuperação ainda precisa de acompanhamento.':'Fiz uma consulta de rotina e cuidei da saúde.',{health:5});return}if(a==='well'){const costs={exercise:0,meditate:0,therapy:180,salon:120,spa:300};if(!(id in costs)||!spend(costs[id]))return;if(id==='exercise'){xp('sport',4);effects({health:6})}if(['meditate','therapy','spa'].includes(id)){w.stress=clamp(w.stress-(id==='therapy'?20:10));effects({happy:6})}if(id==='salon')w.looks=clamp(w.looks+8);if(id==='spa'){w.looks=clamp(w.looks+3);effects({health:3})}tell('Reservei um momento para cuidar de mim.');return}
if(a==='businessnew'){let b=BUSINESSES.find(b=>b.id===id);if(!b||w.company||S.age<18)return;modal(`<h2>Abrir ${b.name.toLowerCase()}</h2><p>O capital inicial de ${money(b.capital)} sai da carteira e fica na empresa. Você pode operar mês a mês. Ao avançar um aniversário, os meses restantes serão concluídos. Parte do capital será usada no estoque inicial.</p>${field('business-name','Nome da empresa',b.name+' '+S.name.split(' ')[0],'text','maxlength="40"')}${btn('Fundar empresa','businessconfirm:'+id,!canSpend(b.capital))}<button class="btn" data-action="close">Voltar</button>`);return}if(a==='businessconfirm'){let b=BUSINESSES.find(b=>b.id===id);if(!b||w.company||S.age<18||!spend(b.capital))return;w.company={type:id,name:$('#business-name').value.trim().slice(0,40)||b.name,capital:b.capital,price:b.price,staff:1,level:1,marketing:0,years:0,last:null};$('#modal').close();tell('Fundei '+w.company.name+'. Minha história como empreendedor começou.');return}if(a.startsWith('business')){let c=w.company;if(!c)return;if(a==='businesssave'){let price=Number($('#product-price').value),staff=Number($('#staff-count').value);if(!Number.isFinite(price)||price<1||price>100000||!Number.isInteger(staff)||staff<0||staff>100){toast('Revise o preço e a quantidade de funcionários.');return}c.price=cents(price);c.staff=staff;tell('Atualizei o preço e a equipe da empresa.');return}if(a==='businessfund'&&spend(10000)){c.capital+=10000;tell('Aportei R$ 10.000 na empresa.')}if(a==='businesswithdraw'&&c.capital>=5000){c.capital-=5000;S.money+=5000;tell('Transferi R$ 5.000 da empresa para minha carteira.')}if(a==='businessmarket'&&c.capital-c.marketing>=3000){c.marketing+=3000;tell('Reservei mais R$ 3.000 em marketing para o próximo ano. O custo será descontado no fechamento.')}if(a==='businessexpand'&&c.capital>=30000){c.capital-=30000;c.level++;tell('Ampliei a operação. Capacidade e custo fixo aumentaram.')}if(a==='businessclose'){modal(`<h2>Encerrar a empresa?</h2><p>O capital de ${money(c.capital)} será transferido à sua carteira, incluindo eventual prejuízo.</p>${btn('Encerrar operações','businesscloseconfirm')}<button class="btn" data-action="close">Voltar</button>`)}if(a==='businesscloseconfirm'){S.money=cents(S.money+c.capital);w.company=null;$('#modal').close();tell('Encerrei minha empresa e liquidei seu capital.')}return}
if(a==='homebuy'){let p=PROPERTIES.find(p=>p.id===id);if(!p||S.age<18)return;modal(`<h2>${p.name}</h2><p>${money(p.price)} à vista ou entrada de 30% (${money(p.price*.3)}) e saldo em 10 parcelas anuais, com acréscimo total de 20% sobre a parte financiada.</p>${btn('Comprar à vista','homeconfirm:'+id+':cash',!canSpend(p.price))}${btn('Dar entrada e financiar','homeconfirm:'+id+':finance',!canSpend(p.price*.3))}<button class="btn" data-action="close">Voltar</button>`);return}if(a==='homeconfirm'){let p=PROPERTIES.find(p=>p.id===id);if(!p||S.age<18||!['cash','finance'].includes(arg)||!spend(p.price*(arg==='cash'?1:.3)))return;let debt=arg==='finance'?cents(p.price*.7*1.2):0;w.homes.push({...p,id:nextFamilyId(),value:p.price,debt,installment:debt/10,condition:100,rented:false,residence:false});$('#modal').close();tell('Comprei '+p.name+'.');return}
if(['homeuse','homerent','homerepair','homesell','homesellconfirm'].includes(a)){let h=w.homes.find(h=>h.id===id);if(!h)return;if(a==='homeuse'){w.homes.forEach(x=>x.residence=false);h.residence=true;h.rented=false;tell('Me mudei para '+h.name+'. O custo de moradia muda no próximo ciclo de boletos.')}if(a==='homerent'&&!h.residence){h.rented=!h.rented;tell(h.rented?'Coloquei '+h.name+' para alugar.':'Encerrei o aluguel de '+h.name+'.')}if(a==='homerepair'&&spend(5000)){h.condition=100;tell('Reformei '+h.name+'.')}if(a==='homesell'){modal(`<h2>Vender ${h.name}?</h2><p>Valor de venda: ${money(h.value*.95)}. Dívida quitada na venda: ${money(h.debt)}. Valor líquido: ${money(h.value*.95-h.debt)}.</p>${btn('Confirmar venda','homesellconfirm:'+id)}<button class="btn" data-action="close">Voltar</button>`)}if(a==='homesellconfirm'){S.money=cents(S.money+h.value*.95-h.debt);S.phone.bills=S.phone.bills.filter(b=>b.paid||!b.key.endsWith('-'+h.id));w.homes=w.homes.filter(x=>x.id!==id);$('#modal').close();tell('Vendi '+h.name+' e quitei seu financiamento.')}return}
if(a==='stock'){let stock=STOCKS.find(s=>s.id===id);if(!stock||S.age<18)return;modal(`<h2>${arg==='buy'?'Comprar':'Vender'} ${stock.symbol}</h2><p>Cotação atual: ${money(w.prices[id])}. Você tem ${w.holdings[id]||0} cotas. As cotações só mudam ao avançar o ano.</p>${field('stock-qty','Quantidade de cotas',1,'number','min="1" step="1"')}${btn('Confirmar operação','stockconfirm:'+id+':'+arg)}<button class="btn" data-action="close">Voltar</button>`);return}if(a==='stockconfirm'){let stock=STOCKS.find(s=>s.id===id),qty=Number($('#stock-qty').value);if(!stock||S.age<18||!Number.isInteger(qty)||qty<1||qty>1e9)return;let price=cents(qty*w.prices[id]);if(arg==='buy'){if(!spend(price))return;w.holdings[id]=(w.holdings[id]||0)+qty;/* payment recorded by shared checkout */}else if(arg==='sell'){if((w.holdings[id]||0)<qty){toast('Você não possui essa quantidade de cotas.');return}w.holdings[id]-=qty;S.money=cents(S.money+price);record('Venda de '+stock.symbol,price)}else return;$('#modal').close();tell('Negociei '+qty+' cotas de '+stock.symbol+'.');return}
if(a==='post'||a==='live'){if(S.age<13)return;const views=Math.max(20,Math.round((w.followers*.3+50+w.skills.art*10)*(.2+Math.random()*3)));let newFollowers=Math.round(views*(.01+Math.random()*.025));if(Math.random()<.12)newFollowers=-Math.min(w.followers,Math.round(w.followers*.015));w.followers=Math.max(0,w.followers+newFollowers);w.posts++;w.stamps.post=S.age;w.fame=clamp(w.fame+(views>10000?2:.2));tell((a==='live'?'Minha live':'Minha publicação')+' teve '+views.toLocaleString('pt-BR')+' visualizações e '+(newFollowers>=0?'ganhou ':'perdeu ')+Math.abs(newFollowers)+' seguidores.');return}if(a==='ad'){if(w.followers<10000)return;let amount=Math.round(w.followers*.018);S.money+=amount;record('Campanha de publicidade',amount);w.followers=Math.round(w.followers*.99);tell('Fiz uma campanha e recebi '+money(amount)+'. Uma parte da audiência não gostou da publicidade.');return}if(a==='interview'){if(w.fame<20)return;xp('speech',3);w.fame=clamp(w.fame+2);tell('Dei uma entrevista sobre minha trajetória.');return}if(a==='release')return releaseDialog(id);if(a==='releaseconfirm')return releaseWork(id);
if(a==='election'){let p={council:['Vereador(a)',18,5000,5000],mayor:['Prefeito(a)',21,20000,14000],governor:['Governador(a)',30,100000,26000],president:['Presidente',35,500000,36000]}[id];if(!p||w.office||w.record||S.age<p[1]||!spend(p[2]))return;let chance=clamp((S.reputation+w.skills.speech+w.approval)/330,.05,.88);if(Math.random()<chance){w.office={name:p[0],years:4};S.job=p[0];S.salary=p[3];w.special=null;tell('Fui eleito(a) '+p[0]+' para um mandato de quatro anos.',{happy:10})}else tell('Não fui eleito(a). A campanha terminou, mas posso melhorar minha reputação e tentar novamente.');return}if(a==='policy'){if(!w.office)return;w.approval=clamp(w.approval+5);xp('speech',2);tell('Priorizei '+({education:'educação',health:'saúde',listen:'o diálogo com a população'}[id]||'a população')+' no meu mandato.');return}
if(a==='trip'||a==='move'){let d=DESTINATIONS[+id];if(!d||S.age<18)return;if(a==='move'){modal(`<h2>Recomeçar em ${d[0]}?</h2><p>A mudança custa ${money(d[2]*3)} e encerra seu trabalho atual. Seus imóveis, aplicativos, família e investimentos são preservados.</p>${btn('Confirmar mudança','moveconfirm:'+id,!canSpend(d[2]*3))}<button class="btn" data-action="close">Voltar</button>`)}else if(spend(d[2])){if(!w.visited.includes(d[0]))w.visited.push(d[0]);tell('Viajei para '+d[0]+' e vivi uma nova experiência.',{happy:12,smarts:2})}return}if(a==='moveconfirm'){let d=DESTINATIONS[+id];if(!d||S.age<18||!spend(d[2]*3))return;S.city=d[0];S.job=null;S.salary=0;w.special=null;w.office=null;if(!w.visited.includes(d[0]))w.visited.push(d[0]);$('#modal').close();tell('Comecei uma nova fase da vida em '+d[0]+'.');return}
if(a==='crime'){let c={shop:['Pequeno furto',400,.4,1],fraud:['Fraude financeira',7000,.65,4],robbery:['Assalto',18000,.8,7]}[id];if(!c||S.age<18)return;modal(`<h2>Essa decisão tem consequências.</h2><p>${c[0]}: risco de detenção de ${c[2]*100}%, pena de ${c[3]} anos no jogo e perda de reputação.</p>${btn('Assumir o risco','crimeconfirm:'+id)}<button class="btn" data-action="close">Desistir</button>`);return}if(a==='crimeconfirm'){let c={shop:[400,.4,1],fraud:[7000,.65,4],robbery:[18000,.8,7]}[id];if(!c||S.age<18)return;w.karma=clamp(w.karma-15);effects({reputation:-12});$('#modal').close();if(Math.random()<c[1]){w.prison=c[2];w.record++;S.job=null;S.salary=0;w.special=null;w.office=null;tell('Fui condenado(a) a '+c[2]+' anos de prisão. Perdi meu trabalho e minha liberdade.',{happy:-15})}else{let amount=Math.round(c[0]*(.4+Math.random()*.6));S.money+=amount;tell('Minha decisão rendeu '+money(amount)+', mas abalou minha reputação.')}return}if(a==='prisonstudy'&&w.prison){effects({smarts:5});xp('discipline',3);tell('Estudei na biblioteca da prisão.');return}if(a==='prisonwork'&&w.prison){if(w.stamps.prisonwork===S.age){toast('O pagamento deste ano já foi recebido.');return}w.stamps.prisonwork=S.age;S.money+=600;tell('Trabalhei durante a pena e recebi R$ 600 neste ano.');return}if(a==='appeal'&&w.prison&&spend(2000)){if(Math.random()<.35){w.prison=Math.max(0,w.prison-2);tell('Meu pedido de revisão reduziu a pena em até dois anos.')}else tell('O pedido de revisão não foi aceito.');return}if(a==='escape'&&w.prison)return startEscape();if(a==='mediation'&&spend(300)){w.karma=clamp(w.karma+8);tell('Busquei mediação para resolver um conflito.',{relation:4});return}
if(a==='penalty'&&S.age>=8)return startPenalty();if(a==='mines'&&S.age>=12)return startMines();if(a==='blackjack'&&S.age>=18&&financeCharge(100,'Blackjack · aposta','cash','wallet',1))return startBlackjack();if(a==='lottery'&&S.age>=18&&financeCharge(10,'Sorteio · bilhete','cash','wallet',1)){const win=Math.random()<.0001;if(win)S.money+=50000;tell(win?'Ganhei R$ 50.000 no sorteio da cidade!':'O bilhete não foi premiado. Perdi os R$ 10 da aposta.');return}
if(a==='heirloom'){if(w.stamps.heirloom===S.age)return;w.stamps.heirloom=S.age;let rare=Math.random()<.08,item=pick(['Relógio antigo','Livro de primeiras edições','Moeda comemorativa','Câmera de filme','Caixa de música','Disco de vinil']);w.collectibles.push({name:item,rarity:rare?'RARO':'MEMÓRIA DE FAMÍLIA',value:Math.round((rare?5000:100)+Math.random()*(rare?10000:800)),age:S.age});tell('Encontrei '+item.toLowerCase()+' no sótão da família.');return}if(a==='collectsell'){let c=w.collectibles[+id];if(!c)return;S.money+=c.value;w.collectibles.splice(+id,1);tell('Vendi '+c.name.toLowerCase()+' por '+money(c.value)+'.');return}}
function releaseDialog(type){let settings={music:['Música',2000,'music'],book:['Livro',1500,'art'],film:['Filme',15000,'acting']}[type];if(!settings||S.age<(type==='film'?18:16))return;modal(`<span class="quiz-count">SEU PRÓXIMO LANÇAMENTO</span><h2>${settings[0]}</h2><p>Produção: ${money(settings[1])}. Habilidade atual: ${S.world.skills[settings[2]]}%. O retorno pode ser menor que o investimento.</p>${field('work-title','Título','Um novo começo','text','maxlength="50"')}${btn('Produzir e lançar','releaseconfirm:'+type,!canSpend(settings[1]))}<button class="btn" data-action="close">Voltar</button>`)}
function releaseWork(type){let settings={music:['Música',2000,'music'],book:['Livro',1500,'art'],film:['Filme',15000,'acting']}[type];if(!settings||S.age<(type==='film'?18:16)||!spend(settings[1]))return;let w=S.world,title=$('#work-title').value.trim().slice(0,50)||'Sem título',rating=Math.round(clamp(w.skills[settings[2]]*.65+Math.random()*35)/10),revenue=Math.round(settings[1]*(rating/5)*(.15+Math.random()*1.8));S.money+=revenue;w.fame=clamp(w.fame+(rating>=7?6:-2));w.works.unshift({title,type:settings[0],rating,revenue,cost:settings[1],age:S.age});record('Receita · '+title,revenue);$('#modal').close();tell('Lancei '+title+'. Nota '+rating+'/10 e resultado de '+money(revenue-settings[1])+'.');openResult('Seu lançamento chegou.',title+' recebeu nota '+rating+'/10. Receita: '+money(revenue)+'. Custo: '+money(settings[1])+'.');}
function inheritDialog(){if(S.alive){toast('A próxima geração começa ao final desta vida.');return}let kids=S.world.family.filter(n=>n.role==='Filho(a)'&&n.alive);if(!kids.length){modal('<h2>Uma história que fica.</h2><p>Não há filhos vivos para continuar a família. Você pode iniciar uma nova vida ou revisitar um ano anterior.</p><button class="btn primary" data-action="new">Nova vida</button><button class="btn" data-action="close">Voltar</button>');return}modal(`<h2>Quem continua essa história?</h2><p>Seu patrimônio será liquidado. A divisão segue o testamento e considera as dívidas existentes.</p>${kids.map(n=>`<button class="btn" data-action="x:inheritconfirm:${n.id}">${esc(n.name)} · ${n.age} anos</button>`).join('')}<button class="btn" data-action="close">Voltar</button>`)}
function inheritLife(id){if(S.alive)return;let kids=S.world.family.filter(n=>n.role==='Filho(a)'&&n.alive),child=kids.find(n=>n.id===id);if(!child)return;const old=S,w=old.world,worth=Math.max(0,netWorth()),share=w.will==='first'?(kids[0].id===id?worth:0):worth/kids.length;S=fresh(child.name,old.city,child.age);lifeInit();S.money=cents(share);S.world.family=w.family.filter(n=>n.id!==id&&n.alive&&n.role==='Filho(a)').map(n=>({...n,role:'Irmão(ã)'}));S.world.generation=w.generation+1;S.world.birthYear=w.birthYear+old.age-child.age;S.world.ancestors=[{name:old.name,age:old.age,job:old.job,worth},...w.ancestors];S.world.achievements=[...w.achievements];S.world.theme=w.theme;S.grade=7;S.degree=child.age>=23;S.world.degree=S.degree?'administration':null;phoneInit();eventPick();log('Comecei uma nova geração com '+money(share)+' de herança.');$('#modal').close();tab='life';section='all';phoneOpen=false;render()}
function miniShell(title,body){modal(`<span class="quiz-count">VIVA · MINIJOGO</span><h2>${title}</h2>${body}<button class="btn" data-mini="leave">Encerrar minijogo</button>`)}
function startPenalty(){mini={type:'penalty',round:0,score:0};drawPenalty()}
function drawPenalty(){miniShell('O próximo gol é seu.',`<p>Cobrança ${mini.round+1}/5 · ${mini.score} gols. Escolha seu canto. A habilidade de esporte aumenta a chance de acertar.</p><div class="goal-board"><span>ESQUERDA</span><span>CENTRO</span><span>DIREITA</span></div><div class="mini-controls">${[0,1,2].map((n)=>`<button class="btn primary" data-mini="kick:${n}">${['Esquerda','Centro','Direita'][n]}</button>`).join('')}</div>`)}
function startMines(){let mines=new Set;while(mines.size<3)mines.add(Math.floor(Math.random()*16));mini={type:'mines',mines:[...mines],opened:[],safe:0};drawMines()}
function drawMines(){miniShell('Operação lógica',`<p>Encontre 5 casas seguras. Há 3 minas escondidas. Os números indicam minas nos oito vizinhos; a primeira casa pode conter uma mina.</p><div class="mines-grid">${Array.from({length:16},(_,i)=>{const opened=mini.opened.includes(i),r=Math.floor(i/4),c=i%4,n=mini.mines.filter(m=>Math.abs(Math.floor(m/4)-r)<=1&&Math.abs(m%4-c)<=1).length;return `<button data-mini="reveal:${i}" ${opened?'disabled':''} aria-label="Linha ${r+1}, coluna ${c+1}">${opened?n||'·':'?'}</button>`}).join('')}</div><p>${mini.safe}/5 casas seguras encontradas.</p>`)}
function drawCard(){return Math.floor(Math.random()*13)+1}
function handValue(hand){let value=hand.reduce((n,c)=>n+(c===1?11:Math.min(10,c)),0),aces=hand.filter(c=>c===1).length;while(value>21&&aces-- >0)value-=10;return value}
function showCards(cards,hide=false){return cards.map((c,i)=>`<span class="playing-card">${hide&&i===1?'?':({1:'A',11:'J',12:'Q',13:'K'}[c]||c)}</span>`).join('')}
function startBlackjack(){mini={type:'blackjack',player:[drawCard(),drawCard()],dealer:[drawCard(),drawCard()]};drawBlackjack()}
function drawBlackjack(){miniShell('Uma rodada de 21',`<p>Aposta: R$ 100 fictícios. Vitória devolve R$ 200; empate devolve R$ 100. Ás vale 1 ou 11.</p><span class="eyebrow">MESA</span><div class="cards-row">${showCards(mini.dealer,true)}</div><span class="eyebrow">SUA MÃO · ${handValue(mini.player)}</span><div class="cards-row">${showCards(mini.player)}</div><div class="mini-controls"><button class="btn primary" data-mini="hit">Pedir carta</button><button class="btn" data-mini="stand">Parar</button></div>`)}
function startEscape(){mini={type:'escape',pos:20,steps:0,walls:[2,7,8,11,13,16,18],exit:4};drawEscape()}
function drawEscape(){miniShell('Um caminho para a saída',`<p>Encontre o caminho até a saída em até 14 movimentos. Casas escuras são paredes. Falhar acrescenta um ano à pena.</p><div class="escape-grid">${Array.from({length:25},(_,i)=>`<span class="${mini.walls.includes(i)?'wall':''} ${mini.pos===i?'player':''} ${mini.exit===i?'exit':''}">${mini.pos===i?'●':mini.exit===i?'SAÍDA':''}</span>`).join('')}</div><p>Movimentos: ${mini.steps}/14</p><div class="mini-controls">${[['up','↑'],['left','←'],['down','↓'],['right','→']].map(([d,l])=>`<button class="btn" data-mini="step:${d}" aria-label="${d}">${l}</button>`).join('')}</div>`)}
function finishMini(title,text){mini=null;render();openResult(title,text)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-mini]');if(!b||b.disabled||!mini)return;const [a,id]=b.dataset.mini.split(':');if(a==='leave'){if(mini.type==='blackjack')log('Encerrei a rodada de 21 e perdi os R$ 100 apostados.');if(mini.type==='escape'){S.world.prison++;log('A tentativa de fuga fracassou e minha pena aumentou em um ano.')}mini=null;$('#modal').close();render();return}if(a==='kick'&&mini.type==='penalty'){let goal=Math.floor(Math.random()*3)!==+id&&Math.random()<.55+S.world.skills.sport/220;if(goal)mini.score++;mini.round++;if(mini.round===5){const score=mini.score;xp('sport',3);if(score>=3){S.world.trophies++;effects({happy:6})}log('Fiz '+score+' gols no campeonato de pênaltis.');finishMini(score>=3?'Troféu conquistado!':'Mais uma experiência em campo.',score+' gols em 5 cobranças. +3 de habilidade esportiva.')}else{toast(goal?'Gol!':'O goleiro defendeu.');drawPenalty()}return}if(a==='reveal'&&mini.type==='mines'){let i=+id;if(i<0||i>15||mini.opened.includes(i))return;if(mini.mines.includes(i)){effects({happy:-2});finishMini('Operação encerrada.','Você encontrou uma mina. Tente novamente e observe as pistas.');return}mini.opened.push(i);mini.safe++;if(mini.safe===5){xp('discipline',7);effects({smarts:3});log('Completei o desafio de operação lógica.');finishMini('Missão cumprida.','Você ganhou 7 de disciplina e 3 de intelecto.')}else drawMines();return}if((a==='hit'||a==='stand')&&mini.type==='blackjack'){if(a==='hit'){mini.player.push(drawCard());if(handValue(mini.player)<=21){drawBlackjack();return}}while(handValue(mini.dealer)<17)mini.dealer.push(drawCard());const p=handValue(mini.player),d=handValue(mini.dealer),win=p<=21&&(d>21||p>d),tie=p<=21&&p===d;if(win)S.money+=200;if(tie)S.money+=100;log('Rodada de 21: '+(win?'ganhei R$ 100.':tie?'empatei.':'perdi R$ 100.'));finishMini(win?'Você venceu.':tie?'Empate.':'A mesa venceu.',`Sua mão: ${p}. Mesa: ${d}. ${win?'R$ 200 retornaram à carteira.':tie?'A aposta de R$ 100 foi devolvida.':'Você perdeu a aposta de R$ 100.'}`);return}if(a==='step'&&mini.type==='escape'){const delta={up:-5,down:5,left:-1,right:1}[id],next=mini.pos+delta;if(delta===undefined||next<0||next>24||((id==='left'||id==='right')&&Math.floor(next/5)!==Math.floor(mini.pos/5))||mini.walls.includes(next)){toast('Esse caminho está bloqueado.');return}mini.pos=next;mini.steps++;if(next===mini.exit){S.world.prison=0;S.world.karma=clamp(S.world.karma-10);log('Escapei da prisão. A condenação continua no meu histórico.');finishMini('Você encontrou a saída.','A fuga encerrou a pena no jogo, mas não apaga seu histórico.')}else if(mini.steps>=14){S.world.prison++;finishMini('A tentativa terminou.','Você foi encontrado(a). Um ano foi acrescentado à pena.')}else drawEscape();}});
$('#modal').addEventListener('cancel',e=>{if(mini)e.preventDefault()});
document.addEventListener('change',e=>{const k=e.target.dataset.worldChange;if(!k)return;if(k==='club'){if(S.age<6||S.age>22){toast('Clubes estudantis estão disponíveis dos 6 aos 22 anos.');render();return}S.world.club=SKILLS.some(s=>s[0]===e.target.value)?e.target.value:null}if(k==='diet')S.world.diet=e.target.value==='premium'?'premium':'balanced';if(k==='will')S.world.will=e.target.value==='first'?'first':'equal';save();render()});
