for(const g of extraEventGroups)for(const [title,text]of g[5])EVENTS.push({id:EVENTS.length,title,text,min:g[1],max:110,category:g[0],kind:'life',requires:g[2],choices:g[3].map((label,i)=>({label,effects:g[4][i]}))});
const originalEffects=effects;effects=function(f){const simple={};for(const[k,v]of Object.entries(f)){if(['fame','karma','stress','looks'].includes(k)&&S.world)S.world[k]=clamp(S.world[k]+v);else simple[k]=v}originalEffects(simple)};
const beforeConditionalEvent=eventPick;eventPick=function(){if(S.world?.prison>0){let pool=EVENTS.filter(e=>e.category==='Reconstrução'&&!S.seen.includes(e.id));if(!pool.length)pool=EVENTS.filter(e=>e.category==='Reconstrução');S.event=pick(pool).id;S.result=null}else beforeConditionalEvent()};
const TAB_LABELS={life:'Minha vida',people:'Pessoas',work:'Ocupação',wallet:'Patrimônio',heart:'Explorar',school:'Educação'};
render=function(){lifeInit();phoneInit();save();renderVivaShell()};
function glassLife(){const w=S.world,e=EVENTS.find(e=>e.id===S.event)||EVENTS[0];return `<div class="life-grid"><aside class="identity-column"><section class="identity-card"><div class="identity-top"><span class="live-chip">${phase()}</span><span class="quiet">Geração ${w.generation}</span></div><div class="identity-avatar">${esc(S.name.split(' ').map(n=>n[0]).slice(0,2).join(''))}</div><h1>${esc(S.name)}</h1><p>${esc(S.job|| (S.age<6?'Descobrindo o mundo':S.age<18?'Estudante':'Escrevendo meu caminho'))}</p><div class="age-display"><strong>${S.age}</strong><span>anos<br>de história</span></div><div class="life-progress"><i style="width:${Math.min(100,S.age)}%"></i></div><div class="identity-meta"><span>${icon('pin')}${esc(S.city)}</span><span>${icon('heart')}${w.married?'Casado(a)':S.partner?'Em um relacionamento':'Uma vida de possibilidades'}</span></div></section><section class="wallet-glance"><span class="eyebrow">SUA CARTEIRA</span><strong>${money(S.money)}</strong><div><span>Renda mensal</span><b>${money(S.salary)}</b></div><div><span>Patrimônio líquido</span><b>${money(netWorth())}</b></div><button data-action="p:home">Organizar no celular ${icon('arrow')}</button></section></aside><section class="story-column"><div class="vital-grid">${[['health','Saúde','heart','pink'],['happy','Felicidade','smile','orange'],['smarts','Intelecto','brain','blue'],['looks','Aparência','star','purple']].map(([id,n,ic,c])=>{let value=id==='looks'?w.looks:S[id];return `<div class="vital tint-${c}"><span class="hub-icon">${icon(ic)}</span><strong>${Math.round(value)}<small>%</small></strong><span>${n}</span><div class="bar"><i style="width:${value}%"></i></div></div>`}).join('')}</div><div class="story-heading"><h2>${S.alive?'A vida acontece agora.':'Uma história que fica.'}</h2><span>${S.age} anos</span></div><article class="decision-card">${S.alive?`<div class="decision-category"><span>${icon(w.prison?'lock':e.kind==='school'?'school':'life')}</span>${e.category}<small>${S.queue+1}/2</small></div><h2>${e.title}</h2><p>${e.text}</p>${S.result?`<div class="choice-result">${icon('check')}<span>${esc(S.result)}</span></div>`:`<div class="decision-choices">${e.choices.map((c,i)=>`<button data-choice="${i}" ${c.effects.money<0&&S.money<-c.effects.money?'disabled':''}><span><b>${c.label}</b><small>${efText(c.effects)}</small></span>${icon('arrow')}</button>`).join('')}</div>`}`:`<span class="decision-category">${icon('medal')} SEU LEGADO</span><h2>Cada escolha fez parte de você.</h2><p>${S.age} anos. ${S.seen.length} acontecimentos. ${w.achievements.length} conquistas. Seu legado pode continuar em uma nova geração.</p><div class="action-ribbon"><button class="btn primary" data-action="x:inherit">Continuar com um herdeiro</button><button class="btn" data-action="x:section:legacy">Ver meu legado</button></div>`}</article>${S.alive?`<button class="advance-glass" data-action="advance" ${!S.result?'disabled':''}><span>${S.queue===0?'Continuar minha história':'Avançar um ano'}<small>${S.queue===0?'Ainda há um acontecimento neste capítulo':'Um novo capítulo. Novas possibilidades.'}</small></span><span>${icon('arrow')}</span></button>`:''}<div class="story-heading"><h2>O que você quer viver?</h2><button data-tab="heart">Explorar tudo ${icon('arrow')}</button></div><div class="quick-grid">${tile('school','Aprender','Escola e formação','section:education','blue')}${tile('heart','Cuidar de mim','Saúde e bem-estar','section:health','pink')}${tile('chart','Construir','Negócios e patrimônio','section:business','green')}${tile('plane','Descobrir','Viagens e experiências','section:travel','purple')}</div>${w.report.length?`<details class="year-report"><summary>${icon('chart')} Resumo do último ano <span>+</span></summary>${w.report.map(r=>`<div><span><b>${esc(r.title)}</b><small>${esc(r.detail)}</small></span><strong>${money(r.amount)}</strong></div>`).join('')}</details>`:''}</section><aside class="memory-column"><section class="memory-panel"><div class="memory-title"><span class="hub-icon">${icon('book')}</span><h2>Seu diário</h2></div><div class="memory-list">${S.history.slice(0,8).map((h,i)=>`<article><div class="memory-dot ${i===0?'current':''}"></div><small>${h.age} ANOS</small><p>${esc(h.text)}</p></article>`).join('')}</div>${btn('Ver conquistas & legado','section:legacy')}</section><section class="moment-card"><span class="hub-icon">${icon('medal')}</span><div><b>${w.achievements.length} conquistas</b><p>Cada uma conta uma história.</p></div></section></aside></div>`}
function wealthPage(){return heading('Tudo o que você constrói','Acompanhe suas conquistas e decida seu próximo passo.')+`<div class="overview-strip">${summary('Patrimônio líquido',money(netWorth()),'wallet')}${summary('Nos bancos',money(S.savings),'chart')}${summary('Veículos',S.assets.filter(a=>a.type==='car').length,'car')}</div><div class="hub-grid">${tile('home','Imóveis','Comprar, financiar e alugar','section:properties','blue')}${tile('chart','Investimentos','Ações e ativos fictícios','section:market','green')}${tile('work','Empresas','Operação e resultados','section:business','purple')}${tile('book','Coleções','Objetos que têm história','section:collection','orange')}</div><section class="finance-phone-card"><span class="hub-icon">${icon('phone')}</span><div><h3>Seu dinheiro também mora no celular.</h3><p>Bancos, boletos, assinaturas e sua garagem continuam nos aplicativos.</p></div><button class="btn primary" data-action="p:home">Abrir celular</button></section>${S.assets.filter(a=>a.type==='home').map(a=>pane(a.name,`<p>Imóvel preservado da sua vida anterior. Valor: ${money(a.price)}.</p><button class="btn" data-action="asset2">Vender por 85% do valor</button>`,'home')).join('')}`}
// Reset sub-navigation before the existing delegated navigation handler renders.
document.addEventListener('click',e=>{if(e.target.closest('[data-tab]'))section='all'},true);
